import{_ as n,o as h,c as o,a3 as d}from"./chunks/framework.MGD2uYU7.js";const b=JSON.parse('{"title":"05 — Web Nhà ở thương mại (NOTM): Quy trình bán hàng","description":"","frontmatter":{},"headers":[],"relativePath":"guide/05-web-notm.md","filePath":"guide/05-web-notm.md","lastUpdated":null}'),c={name:"guide/05-web-notm.md"};function g(r,t,e,i,a,s){return h(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="_05-—-web-nha-o-thuong-mai-notm-quy-trinh-ban-hang" tabindex="-1">05 — Web Nhà ở thương mại (NOTM): Quy trình bán hàng <a class="header-anchor" href="#_05-—-web-nha-o-thuong-mai-notm-quy-trinh-ban-hang" aria-label="Permalink to &quot;05 — Web Nhà ở thương mại (NOTM): Quy trình bán hàng&quot;">​</a></h1><p><strong>Dự án</strong>: Hệ thống phần mềm &amp; website cho CĐT An Phúc — dự án An Phúc Imperia <strong>Status</strong>: Draft gửi khách hàng rà soát — <strong>Updated</strong>: 2026-10-11 — <strong>Version</strong>: 2.0 <strong>Nguồn</strong>: Sheet <code>04_WEB_NOTM</code> (Google Sheet MAYogu × An Phúc)</p><blockquote><p>Doc này là bản đặc tả trung thực của sheet: bám sát từng dòng, không tự thêm tính năng. Phần chưa rõ đánh dấu 🟡 và dồn về mục &quot;Cần xác nhận&quot;.</p></blockquote><hr><h2 id="_0-cach-đoc-doc-nay-nguyen-tac-trung-thuc" tabindex="-1">0. Cách đọc doc này (nguyên tắc trung thực) <a class="header-anchor" href="#_0-cach-đoc-doc-nay-nguyen-tac-trung-thuc" aria-label="Permalink to &quot;0. Cách đọc doc này (nguyên tắc trung thực)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhãn</th><th>Ý nghĩa (theo doc <code>00</code> §2)</th></tr></thead><tbody><tr><td>✅ <strong>ĐÃ CHỐT</strong></td><td>Sheet <code>04_WEB_NOTM</code> khẳng định, có dòng/cột cụ thể để trace</td></tr><tr><td>🟡 <strong>CẦN XÁC NHẬN / CẦN BỔ SUNG</strong></td><td>Sheet bỏ trống, không nêu, hoặc chỉ nêu một phía → dồn về §7</td></tr><tr><td>🔵 <strong>ĐỀ XUẤT (chưa duyệt)</strong></td><td>Sheet ghi &quot;Đề xuất…&quot; / &quot;Cân nhắc…&quot;</td></tr></tbody></table><p><strong>Ghi nhận về trạng thái nguồn (quan trọng, để tránh hiểu lầm khi rà soát):</strong></p><ol><li><strong>Sheet <code>04_WEB_NOTM</code> không có dòng nào ghi &quot;Đề xuất…&quot; hay &quot;Cân nhắc…&quot;</strong> → doc này <strong>không có hạng mục 🔵</strong>. Mọi nội dung ở §2–§3 đều là ✅ (nguyên văn sheet) hoặc 🟡 (sheet không nêu).</li><li><strong>Cột <code>GHI CHÚ</code> của sheet trống ở cả 8 dòng</strong> (header sheet có 5 cột: <code>GIAI ĐOẠN | CHỦ ĐẦU TƯ | KHÁCH HÀNG | GIAO DIỆN / DỮ LIỆU | GHI CHÚ</code>) → 🟡 <strong>OQ‑NOTM‑10</strong>.</li><li><strong>Cột <code>CHỦ ĐẦU TƯ</code> trống ở bước 1, 2, 3</strong> — sheet để trống phần việc của CĐT trong 3 bước này; doc ghi đúng như vậy, <strong>không tự điền</strong>.</li><li>Text trong <strong>ngoặc kép</strong> là <strong>nguyên văn sheet</strong>. Doc <strong>không</strong> bổ sung: wireframe/màn hình chi tiết, API, ERD/data dictionary, số tiền – tỷ lệ – số đợt thanh toán, thời hạn OTP, quy tắc chọn/đổi căn, phân quyền chi tiết, luồng trạng thái — vì sheet không nêu.</li><li>Doc có sử dụng một số thông tin nền từ <strong>Sheet 01 / doc <code>00</code></strong> (vai trò, mô hình 5 nguồn) và <strong>Sheet 02 / doc <code>03</code></strong> (chính sách NOTM). Những chỗ này <strong>ghi rõ nguồn lấy từ sheet nào</strong>, không trình bày như thể nằm trong sheet <code>04_WEB_NOTM</code>.</li></ol><hr><h2 id="_1-gioi-thieu-web-notm" tabindex="-1">1. Giới thiệu Web NOTM <a class="header-anchor" href="#_1-gioi-thieu-web-notm" aria-label="Permalink to &quot;1. Giới thiệu Web NOTM&quot;">​</a></h2><h3 id="_1-1-sheet-noi-gi-nguyen-van" tabindex="-1">1.1 Sheet nói gì (nguyên văn) <a class="header-anchor" href="#_1-1-sheet-noi-gi-nguyen-van" aria-label="Permalink to &quot;1.1 Sheet nói gì (nguyên văn)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hạng mục</th><th>Nội dung nguyên văn sheet <code>04_WEB_NOTM</code></th></tr></thead><tbody><tr><td>Dòng tiêu đề</td><td><strong>&quot;WEB NHÀ Ở THƯƠNG MẠI – WEBSITE SẢN PHẨM NOTM&quot;</strong></td></tr><tr><td>Ghi chú đầu sheet</td><td><strong>&quot;Nội dung được chuyển từ nhánh WEBSITE SẢN PHẨM NOTM trong sơ đồ XMind.&quot;</strong></td></tr><tr><td>Cấu trúc cột</td><td><code>GIAI ĐOẠN</code> | <code>CHỦ ĐẦU TƯ</code> | <code>KHÁCH HÀNG</code> | <code>GIAO DIỆN / DỮ LIỆU</code> | <code>GHI CHÚ</code></td></tr><tr><td>Số dòng nghiệp vụ</td><td><strong>8 dòng</strong>, đánh STT 1–8</td></tr></tbody></table><p>✅ Như vậy: <strong>Web NOTM = &quot;website sản phẩm NOTM&quot;</strong> — website nghiệp vụ phục vụ <strong>quy trình bán hàng nhà ở thương mại gồm 8 bước</strong>, nội dung được chuyển từ nhánh <em>WEBSITE SẢN PHẨM NOTM</em> trong sơ đồ XMind của MAYogu × An Phúc.</p><h3 id="_1-2-ban-chat-pham-vi-✅-theo-sheet" tabindex="-1">1.2 Bản chất &amp; phạm vi (✅ theo sheet) <a class="header-anchor" href="#_1-2-ban-chat-pham-vi-✅-theo-sheet" aria-label="Permalink to &quot;1.2 Bản chất &amp; phạm vi (✅ theo sheet)&quot;">​</a></h3><ul><li>Sheet mô tả <strong>song song hai phía</strong> cho mỗi giai đoạn: việc <strong>CHỦ ĐẦU TƯ</strong> làm và việc <strong>KHÁCH HÀNG</strong> làm, kèm <strong>GIAO DIỆN / DỮ LIỆU</strong> phát sinh.</li><li><strong>8 giai đoạn</strong> (đúng thứ tự STT sheet): Đăng ký tài khoản → Đăng nhập → Khôi phục tài khoản → Tư vấn chọn căn → Chốt căn hộ → Ký hợp đồng &amp; đặt cọc → Thanh toán → Bàn giao.</li><li><strong>Bước 1–3</strong> là nhóm <strong>tài khoản khách hàng</strong> (sheet <strong>để trống</strong> cột CHỦ ĐẦU TƯ).</li><li><strong>Bước 4–8</strong> là nhóm <strong>nghiệp vụ bán hàng</strong>, có phần việc của CĐT ở cả 5 bước.</li><li>Phạm vi sheet dừng ở <strong>mô tả nghiệp vụ theo giai đoạn</strong>; <strong>không</strong> có: bộ trạng thái, bảng phân quyền, quy tắc tính giá, danh mục màn hình, ràng buộc dữ liệu (xem §7).</li></ul><h3 id="_1-3-vi-tri-trong-he-thong-web-notm-la-nguon-03" tabindex="-1">1.3 Vị trí trong hệ thống: Web NOTM là &quot;Nguồn 03&quot; <a class="header-anchor" href="#_1-3-vi-tri-trong-he-thong-web-notm-la-nguon-03" aria-label="Permalink to &quot;1.3 Vị trí trong hệ thống: Web NOTM là &quot;Nguồn 03&quot;&quot;">​</a></h3><p><em>(nguồn: <strong>Sheet 01</strong> — tổng hợp tại doc <code>00</code> §4; <strong>không</strong> phải nội dung sheet <code>04_WEB_NOTM</code>)</em></p><p>✅ Web NOTM là <strong>Nguồn 03</strong> trong mô hình &quot;5 nguồn → 1 phần mềm tổng&quot;: vai trò <strong>&quot;Lead và bán hàng NOTM&quot;</strong>, dữ liệu chuyển về Phần mềm tổng (CRM): <strong>&quot;Thông tin khách hàng, sản phẩm quan tâm, lịch sử tư vấn/giao dịch&quot;</strong>. Chi tiết chức năng CRM ở doc <code>02</code>; cơ chế đồng bộ cụ thể của Web NOTM <strong>chưa được nêu</strong> → 🟡 <strong>OQ‑NOTM‑06</strong> (§4).</p><h3 id="_1-4-khac-biet-so-voi-web-noxh-doc-04-—-ghi-nhan-than-trong" tabindex="-1">1.4 Khác biệt so với Web NOXH (doc <code>04</code>) — ghi nhận thận trọng <a class="header-anchor" href="#_1-4-khac-biet-so-voi-web-noxh-doc-04-—-ghi-nhan-than-trong" aria-label="Permalink to &quot;1.4 Khác biệt so với Web NOXH (doc `04`) — ghi nhận thận trọng&quot;">​</a></h3><p>Bảng dưới so sánh <strong>những gì mỗi sheet có nêu</strong>. Cột NOTM chỉ ghi nhận <strong>&quot;sheet không nêu/không có bước tương ứng&quot;</strong> — <strong>không</strong> suy diễn thành kết luận nghiệp vụ hay pháp lý.</p><p><em>(Cột &quot;Web NOXH&quot; tổng hợp từ doc <code>00</code> §5, §7.2 &amp; §9 — nguồn Sheet 03 — chỉ dùng để so sánh; chi tiết đầy đủ ở doc <code>04</code>.)</em></p><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Web NOXH — sheet <code>03</code> (doc <code>04</code>)</th><th>Web NOTM — sheet <code>04</code> (doc này)</th></tr></thead><tbody><tr><td>Số bước quy trình</td><td>20 bước</td><td><strong>8 bước</strong> ✅</td></tr><tr><td>Xác thực OTP khi đăng ký</td><td>Có (bước 1)</td><td><strong>Có</strong> — &quot;Xác thực số điện thoại qua OTP&quot; (bước 1) ✅</td></tr><tr><td>Công cụ <strong>tự kiểm tra điều kiện</strong> mua</td><td>Có (bước 3 — kèm câu hỏi &quot;cần tổ hợp thông tin + đáp án&quot;)</td><td><strong>Sheet 04 KHÔNG có bước/công cụ tương ứng</strong> ✅ (ghi nhận sự vắng mặt)</td></tr><tr><td><strong>Nộp hồ sơ xét duyệt / Sở Xây dựng</strong></td><td>Có (nộp, kiểm tra, đối chiếu bản gốc, trình Sở)</td><td><strong>Sheet 04 KHÔNG có</strong> ✅</td></tr><tr><td><strong>Bốc thăm / thỏa thuận chọn căn theo thứ tự</strong></td><td>Có (bước 16–17)</td><td><strong>Sheet 04 KHÔNG có</strong>; thay bằng <strong>&quot;Tư vấn chọn căn&quot;</strong> (bước 4) + <strong>&quot;Chốt căn hộ&quot;</strong> (bước 5) ✅</td></tr><tr><td>Bộ <strong>trạng thái hồ sơ</strong> (state machine)</td><td>Có (Sheet 03 liệt kê đầy đủ)</td><td><strong>Sheet 04 KHÔNG liệt kê trạng thái nào</strong> 🟡</td></tr><tr><td>Bản chất sản phẩm</td><td>Nhà ở xã hội — có chính sách hỗ trợ của Nhà nước, bán đúng đối tượng &amp; điều kiện luật định (doc <code>00</code> §8)</td><td><strong>Nhà ở thương mại — căn hộ bán theo cơ chế thị trường</strong> (doc <code>00</code> §8) ✅</td></tr></tbody></table><p><strong>Diễn giải (thận trọng, không bịa):</strong> NOTM là nhà ở thương mại bán theo <strong>cơ chế thị trường</strong>; việc sheet <code>04_WEB_NOTM</code> <strong>không có</strong> các bước <em>tự kiểm tra điều kiện</em>, <em>nộp hồ sơ xét duyệt Sở Xây dựng</em>, <em>bốc thăm / chọn căn theo thứ tự</em> là <strong>phù hợp với bản chất đó</strong> — ở NOTM, khách <strong>trao đổi nhu cầu &amp; tài chính với CĐT</strong> rồi CĐT <strong>ghi nhận/chốt căn hộ</strong>. Tài liệu <strong>chỉ ghi nhận &quot;sheet không nêu&quot;</strong>, <strong>không</strong> kết luận rằng khâu bán NOTM không chịu ràng buộc nào khác. Các điều kiện để sản phẩm NOTM được đưa vào kinh doanh/ký kết nằm ở doc <code>03</code> (F.B.5) và thuộc phạm vi pháp lý → cần CĐT xác nhận (<strong>OQ‑NOTM‑01</strong>).</p><h3 id="_1-5-vai-tro-actor-—-sheet-04-neu-toi-đau" tabindex="-1">1.5 Vai trò (actor) — sheet 04 nêu tới đâu <a class="header-anchor" href="#_1-5-vai-tro-actor-—-sheet-04-neu-toi-đau" aria-label="Permalink to &quot;1.5 Vai trò (actor) — sheet 04 nêu tới đâu&quot;">​</a></h3><p><em>(định nghĩa mã vai trò: doc <code>00</code> §7.1, nguồn Sheet 03 — mục PHÂN QUYỀN)</em></p><table tabindex="0"><thead><tr><th>Mã vai trò</th><th>Sheet <code>04_WEB_NOTM</code> gọi là</th><th>Xuất hiện ở bước</th><th>Trạng thái</th></tr></thead><tbody><tr><td><code>CUSTOMER</code></td><td>Cột <strong>&quot;KHÁCH HÀNG&quot;</strong></td><td>1–8 (đủ 8 bước)</td><td>✅ sheet có cột riêng cho khách</td></tr><tr><td><em>(phía CĐT — chưa rõ mã)</em></td><td>Cột <strong>&quot;CHỦ ĐẦU TƯ&quot;</strong></td><td>4, 5, 6, 7, 8 (bước 1–3 <strong>để trống</strong>)</td><td>🟡 sheet <strong>không nói rõ</strong> là <code>ADMIN</code>, <code>STAFF</code> hay <code>ACCOUNTANT</code> → <strong>OQ‑NOTM‑07</strong></td></tr><tr><td><code>ADMIN</code></td><td>Không nêu</td><td>—</td><td>🟡 sheet 04 không gán</td></tr><tr><td><code>STAFF</code> (NV kinh doanh / soát hồ sơ)</td><td>Không nêu</td><td>—</td><td>🟡 sheet 04 không gán (bước 4 &quot;Tư vấn khách hàng…&quot; không ghi ai tư vấn)</td></tr><tr><td><code>ACCOUNTANT</code> (Kế toán)</td><td>Không nêu</td><td>—</td><td>🟡 bước 7 chỉ ghi CĐT &quot;Theo dõi tiến độ thanh toán&quot;, <strong>không</strong> gán cho kế toán</td></tr><tr><td><code>DOC</code> (Sở Xây dựng)</td><td>Không nêu</td><td>—</td><td>✅ (phù hợp: sheet 04 không có bước xét duyệt/Sở)</td></tr></tbody></table><hr><h2 id="_2-quy-trinh-ban-hang-8-buoc-—-bang-trung-thuc-theo-sheet" tabindex="-1">2. Quy trình bán hàng 8 bước — bảng trung thực theo sheet <a class="header-anchor" href="#_2-quy-trinh-ban-hang-8-buoc-—-bang-trung-thuc-theo-sheet" aria-label="Permalink to &quot;2. Quy trình bán hàng 8 bước — bảng trung thực theo sheet&quot;">​</a></h2><p><strong>Bảng gốc sheet <code>04_WEB_NOTM</code></strong> (giữ nguyên ngôn từ; <code>(sheet để trống)</code> = ô trống trong sheet):</p><table tabindex="0"><thead><tr><th>STT</th><th>GIAI ĐOẠN</th><th>CHỦ ĐẦU TƯ</th><th>KHÁCH HÀNG</th><th>GIAO DIỆN / DỮ LIỆU</th><th>Nhãn</th></tr></thead><tbody><tr><td>1</td><td>Đăng ký tài khoản</td><td><em>(sheet để trống)</em></td><td>Xác thực số điện thoại qua OTP; nhập Họ tên, CCCD; tạo tài khoản.</td><td>Tài khoản khách hàng</td><td>✅</td></tr><tr><td>2</td><td>Đăng nhập</td><td><em>(sheet để trống)</em></td><td>Đăng nhập bằng SĐT hoặc CCCD + mật khẩu.</td><td>Màn hình đăng nhập</td><td>✅</td></tr><tr><td>3</td><td>Khôi phục tài khoản</td><td><em>(sheet để trống)</em></td><td>Lấy lại mật khẩu qua email hoặc số điện thoại.</td><td>Chức năng lấy lại mật khẩu</td><td>✅</td></tr><tr><td>4</td><td>Tư vấn chọn căn</td><td>Tư vấn khách hàng chọn căn hộ theo nhu cầu và tài chính.</td><td>Trao đổi nhu cầu và tài chính với CĐT.</td><td>Thông tin nhu cầu + sản phẩm quan tâm</td><td>✅</td></tr><tr><td>5</td><td>Chốt căn hộ</td><td>Ghi nhận/chốt căn hộ; thông báo hướng dẫn ký hợp đồng và đặt cọc.</td><td>Chốt căn hộ.</td><td>Căn hộ được chọn/chốt</td><td>✅</td></tr><tr><td>6</td><td>Ký hợp đồng &amp; đặt cọc</td><td>Thông báo/hướng dẫn khách hàng đến ký hợp đồng và đặt cọc tiền mua căn hộ.</td><td>Đến theo hướng dẫn của CĐT.</td><td>Hợp đồng + thông tin đặt cọc</td><td>✅</td></tr><tr><td>7</td><td>Thanh toán</td><td>Theo dõi tiến độ thanh toán.</td><td>Thanh toán tiền theo tiến độ.</td><td>Lịch/tiến độ thanh toán</td><td>✅</td></tr><tr><td>8</td><td>Bàn giao</td><td>Thông báo lịch bàn giao.</td><td>Đến nhận bàn giao căn hộ theo thông báo.</td><td>Thông tin bàn giao</td><td>✅</td></tr></tbody></table><blockquote><p>Cột <code>GHI CHÚ</code> của sheet <strong>trống ở cả 8 dòng</strong> → 🟡 <strong>OQ‑NOTM‑10</strong>.</p></blockquote><p><strong>Thứ tự 8 giai đoạn đúng như sheet liệt kê</strong> (sheet <strong>không</strong> mô tả điều kiện chuyển bước, nhánh rẽ hay ngoại lệ → 🟡 §7):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 Đăng ký tài khoản → 2 Đăng nhập → 3 Khôi phục tài khoản</span></span>\n<span class="line"><span>→ 4 Tư vấn chọn căn → 5 Chốt căn hộ → 6 Ký hợp đồng &amp; đặt cọc</span></span>\n<span class="line"><span>→ 7 Thanh toán → 8 Bàn giao</span></span></code></pre></div><p><em>(Sơ đồ trên chỉ là cách trình bày lại STT 1–8 của sheet, không phải state machine. Sheet 04 không có bộ trạng thái như Sheet 03.)</em></p><hr><h2 id="_3-yeu-cau-chuc-nang-—-fr‐notm‐01-fr‐notm‐08" tabindex="-1">3. Yêu cầu chức năng — FR‑NOTM‑01 … FR‑NOTM‑08 <a class="header-anchor" href="#_3-yeu-cau-chuc-nang-—-fr‐notm‐01-fr‐notm‐08" aria-label="Permalink to &quot;3. Yêu cầu chức năng — FR‑NOTM‑01 … FR‑NOTM‑08&quot;">​</a></h2><p>Mỗi FR dưới đây <strong>chuyển đúng 1 dòng sheet</strong> thành yêu cầu chức năng. Phần &quot;Sheet không nêu&quot; liệt kê khoảng trống <strong>để CĐT bổ sung</strong>, <strong>không</strong> phải tính năng đề xuất.</p><h3 id="fr‐notm‐01-—-đang-ky-tai-khoan-✅" tabindex="-1">FR‑NOTM‑01 — Đăng ký tài khoản ✅ <a class="header-anchor" href="#fr‐notm‐01-—-đang-ky-tai-khoan-✅" aria-label="Permalink to &quot;FR‑NOTM‑01 — Đăng ký tài khoản ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 1 — GIAI ĐOẠN: &quot;Đăng ký tài khoản&quot;</td></tr><tr><td>Actor</td><td><code>CUSTOMER</code> (sheet <strong>để trống</strong> cột CHỦ ĐẦU TƯ)</td></tr><tr><td>Mô tả (bám sheet)</td><td>Khách hàng <strong>xác thực số điện thoại qua OTP</strong>, <strong>nhập Họ tên, CCCD</strong>, sau đó <strong>tạo tài khoản</strong>.</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Tài khoản khách hàng&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 Trường email (liên quan bước 3); số lần gửi lại / thời hạn OTP; quy tắc mật khẩu; ràng buộc trùng SĐT/CCCD; ai duyệt tài khoản. → <strong>OQ‑NOTM‑02, OQ‑NOTM‑05</strong></td></tr></tbody></table><h3 id="fr‐notm‐02-—-đang-nhap-✅" tabindex="-1">FR‑NOTM‑02 — Đăng nhập ✅ <a class="header-anchor" href="#fr‐notm‐02-—-đang-nhap-✅" aria-label="Permalink to &quot;FR‑NOTM‑02 — Đăng nhập ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 2 — GIAI ĐOẠN: &quot;Đăng nhập&quot;</td></tr><tr><td>Actor</td><td><code>CUSTOMER</code> (sheet <strong>để trống</strong> cột CHỦ ĐẦU TƯ)</td></tr><tr><td>Mô tả (bám sheet)</td><td>Khách hàng <strong>đăng nhập bằng SĐT hoặc CCCD + mật khẩu</strong>.</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Màn hình đăng nhập&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 Có cần OTP/xác thực bổ sung khi đăng nhập hay khi giao dịch không (bước 1 có OTP, bước 2 sheet chỉ ghi mật khẩu); xử lý sai mật khẩu/khoá tài khoản. → <strong>OQ‑NOTM‑05</strong></td></tr></tbody></table><h3 id="fr‐notm‐03-—-khoi-phuc-tai-khoan-✅" tabindex="-1">FR‑NOTM‑03 — Khôi phục tài khoản ✅ <a class="header-anchor" href="#fr‐notm‐03-—-khoi-phuc-tai-khoan-✅" aria-label="Permalink to &quot;FR‑NOTM‑03 — Khôi phục tài khoản ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 3 — GIAI ĐOẠN: &quot;Khôi phục tài khoản&quot;</td></tr><tr><td>Actor</td><td><code>CUSTOMER</code> (sheet <strong>để trống</strong> cột CHỦ ĐẦU TƯ)</td></tr><tr><td>Mô tả (bám sheet)</td><td>Khách hàng <strong>lấy lại mật khẩu qua email hoặc số điện thoại</strong>.</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Chức năng lấy lại mật khẩu&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 <strong>Email được thu thập ở bước nào</strong> (bước 1 sheet chỉ ghi Họ tên, CCCD + xác thực SĐT); kênh gửi (SMS/email); nội dung thông báo. → <strong>OQ‑NOTM‑02</strong></td></tr></tbody></table><h3 id="fr‐notm‐04-—-tu-van-chon-can-✅" tabindex="-1">FR‑NOTM‑04 — Tư vấn chọn căn ✅ <a class="header-anchor" href="#fr‐notm‐04-—-tu-van-chon-can-✅" aria-label="Permalink to &quot;FR‑NOTM‑04 — Tư vấn chọn căn ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 4 — GIAI ĐOẠN: &quot;Tư vấn chọn căn&quot;</td></tr><tr><td>Actor</td><td>Cột CHỦ ĐẦU TƯ <strong>có nội dung</strong> (chưa rõ mã vai trò 🟡) + <code>CUSTOMER</code></td></tr><tr><td>Mô tả (bám sheet)</td><td><strong>CĐT</strong>: &quot;Tư vấn khách hàng chọn căn hộ theo nhu cầu và tài chính.&quot; — <strong>Khách hàng</strong>: &quot;Trao đổi nhu cầu và tài chính với CĐT.&quot;</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Thông tin nhu cầu + sản phẩm quan tâm&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 Kênh tư vấn (trực tiếp / điện thoại / trên web); ai phía CĐT thực hiện (<code>STAFF</code>?); có màn hình xem danh sách căn – diện tích – mặt bằng trên Web NOTM không; tiêu chí &quot;nhu cầu và tài chính&quot; gồm những trường gì. → <strong>OQ‑NOTM‑06, OQ‑NOTM‑07, OQ‑NOTM‑08</strong></td></tr></tbody></table><h3 id="fr‐notm‐05-—-chot-can-ho-✅" tabindex="-1">FR‑NOTM‑05 — Chốt căn hộ ✅ <a class="header-anchor" href="#fr‐notm‐05-—-chot-can-ho-✅" aria-label="Permalink to &quot;FR‑NOTM‑05 — Chốt căn hộ ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 5 — GIAI ĐOẠN: &quot;Chốt căn hộ&quot;</td></tr><tr><td>Actor</td><td>CĐT (chưa rõ mã vai trò 🟡) + <code>CUSTOMER</code></td></tr><tr><td>Mô tả (bám sheet)</td><td><strong>CĐT</strong>: &quot;Ghi nhận/chốt căn hộ; thông báo hướng dẫn ký hợp đồng và đặt cọc.&quot; — <strong>Khách hàng</strong>: &quot;Chốt căn hộ.&quot;</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Căn hộ được chọn/chốt&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 Cơ chế &quot;chốt&quot; (thao tác trên web hay ngoại tuyến rồi cập nhật lên hệ thống); một căn có thể được nhiều khách chốt không; có trạng thái/khoá căn không; có cho đổi/huỷ sau khi chốt không; nội dung &amp; kênh &quot;thông báo hướng dẫn&quot;. → <strong>OQ‑NOTM‑04</strong></td></tr></tbody></table><h3 id="fr‐notm‐06-—-ky-hop-đong-đat-coc-✅" tabindex="-1">FR‑NOTM‑06 — Ký hợp đồng &amp; đặt cọc ✅ <a class="header-anchor" href="#fr‐notm‐06-—-ky-hop-đong-đat-coc-✅" aria-label="Permalink to &quot;FR‑NOTM‑06 — Ký hợp đồng &amp; đặt cọc ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 6 — GIAI ĐOẠN: &quot;Ký hợp đồng &amp; đặt cọc&quot;</td></tr><tr><td>Actor</td><td>CĐT (chưa rõ mã vai trò 🟡) + <code>CUSTOMER</code></td></tr><tr><td>Mô tả (bám sheet)</td><td><strong>CĐT</strong>: &quot;Thông báo/hướng dẫn khách hàng đến ký hợp đồng và đặt cọc tiền mua căn hộ.&quot; — <strong>Khách hàng</strong>: &quot;Đến theo hướng dẫn của CĐT.&quot;</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Hợp đồng + thông tin đặt cọc&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 Chi tiết quy trình đặt cọc &amp; ký kết (mức cọc, hồ sơ mang theo, hợp đồng mẫu, địa điểm, hình thức trực tiếp hay trực tuyến — sheet dùng từ &quot;Đến&quot;); thông báo qua kênh nào; dữ liệu hợp đồng/đặt cọc có nhập vào CRM không, ai nhập. → <strong>OQ‑NOTM‑01</strong>; chính sách công bố: doc <code>03</code> (F.B.5) 🟡</td></tr></tbody></table><h3 id="fr‐notm‐07-—-thanh-toan-✅" tabindex="-1">FR‑NOTM‑07 — Thanh toán ✅ <a class="header-anchor" href="#fr‐notm‐07-—-thanh-toan-✅" aria-label="Permalink to &quot;FR‑NOTM‑07 — Thanh toán ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 7 — GIAI ĐOẠN: &quot;Thanh toán&quot;</td></tr><tr><td>Actor</td><td>CĐT (chưa rõ mã vai trò 🟡) + <code>CUSTOMER</code></td></tr><tr><td>Mô tả (bám sheet)</td><td><strong>CĐT</strong>: &quot;Theo dõi tiến độ thanh toán.&quot; — <strong>Khách hàng</strong>: &quot;Thanh toán tiền theo tiến độ.&quot;</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Lịch/tiến độ thanh toán&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 Số đợt, tỷ lệ, mốc thời gian, hình thức thanh toán; &quot;tiến độ&quot; lấy từ đâu (nhập tay hay đối soát phần mềm kế toán — doc <code>02</code> nêu liên kết kế toán cho trạng thái/số tiền thanh toán); khách có xem lịch thanh toán của mình trên web không. → <strong>OQ‑NOTM‑03</strong>; chính sách: doc <code>03</code> (F.B.4) 🟡</td></tr></tbody></table><h3 id="fr‐notm‐08-—-ban-giao-✅" tabindex="-1">FR‑NOTM‑08 — Bàn giao ✅ <a class="header-anchor" href="#fr‐notm‐08-—-ban-giao-✅" aria-label="Permalink to &quot;FR‑NOTM‑08 — Bàn giao ✅&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Sheet dòng</td><td>STT 8 — GIAI ĐOẠN: &quot;Bàn giao&quot;</td></tr><tr><td>Actor</td><td>CĐT (chưa rõ mã vai trò 🟡) + <code>CUSTOMER</code></td></tr><tr><td>Mô tả (bám sheet)</td><td><strong>CĐT</strong>: &quot;Thông báo lịch bàn giao.&quot; — <strong>Khách hàng</strong>: &quot;Đến nhận bàn giao căn hộ theo thông báo.&quot;</td></tr><tr><td>Giao diện / dữ liệu (nguyên văn)</td><td><strong>&quot;Thông tin bàn giao&quot;</strong></td></tr><tr><td>Sheet không nêu</td><td>🟡 Kênh &amp; nội dung thông báo; &quot;Thông tin bàn giao&quot; gồm những trường gì; có lưu vết xác nhận đã nhận bàn giao trên hệ thống không. → <strong>OQ‑NOTM‑09</strong></td></tr></tbody></table><p><strong>Bảng trace FR ↔ sheet:</strong></p><table tabindex="0"><thead><tr><th>FR</th><th>STT sheet</th><th>GIAI ĐOẠN (nguyên văn)</th><th>Cột CHỦ ĐẦU TƯ</th></tr></thead><tbody><tr><td>FR‑NOTM‑01</td><td>1</td><td>Đăng ký tài khoản</td><td><em>(trống)</em></td></tr><tr><td>FR‑NOTM‑02</td><td>2</td><td>Đăng nhập</td><td><em>(trống)</em></td></tr><tr><td>FR‑NOTM‑03</td><td>3</td><td>Khôi phục tài khoản</td><td><em>(trống)</em></td></tr><tr><td>FR‑NOTM‑04</td><td>4</td><td>Tư vấn chọn căn</td><td>Có nội dung</td></tr><tr><td>FR‑NOTM‑05</td><td>5</td><td>Chốt căn hộ</td><td>Có nội dung</td></tr><tr><td>FR‑NOTM‑06</td><td>6</td><td>Ký hợp đồng &amp; đặt cọc</td><td>Có nội dung</td></tr><tr><td>FR‑NOTM‑07</td><td>7</td><td>Thanh toán</td><td>Có nội dung</td></tr><tr><td>FR‑NOTM‑08</td><td>8</td><td>Bàn giao</td><td>Có nội dung</td></tr></tbody></table><hr><h2 id="_4-du-lieu-đo-ve-phan-mem-tong-crm-—-web-notm-la-nguon-03" tabindex="-1">4. Dữ liệu đổ về Phần mềm tổng (CRM) — Web NOTM là Nguồn 03 <a class="header-anchor" href="#_4-du-lieu-đo-ve-phan-mem-tong-crm-—-web-notm-la-nguon-03" aria-label="Permalink to &quot;4. Dữ liệu đổ về Phần mềm tổng (CRM) — Web NOTM là Nguồn 03&quot;">​</a></h2><p>✅ Theo doc <code>00</code> §4 (nguồn <strong>Sheet 01</strong>), Nguồn 03 — Web Nhà ở thương mại chuyển về Phần mềm tổng: <strong>&quot;Thông tin khách hàng, sản phẩm quan tâm, lịch sử tư vấn/giao dịch&quot;</strong>. Đối chiếu với cột <code>GIAO DIỆN / DỮ LIỆU</code> của sheet <code>04_WEB_NOTM</code>:</p><table tabindex="0"><thead><tr><th>Nhóm dữ liệu về CRM (Sheet 01 / doc <code>00</code>)</th><th>Dữ liệu sheet <code>04_WEB_NOTM</code> nêu ở bước</th><th>Nhãn</th></tr></thead><tbody><tr><td>Thông tin khách hàng</td><td>B1 <strong>&quot;Tài khoản khách hàng&quot;</strong> (SĐT xác thực qua OTP, Họ tên, CCCD); B2 <strong>&quot;Màn hình đăng nhập&quot;</strong></td><td>✅ có trong sheet 04</td></tr><tr><td>Sản phẩm quan tâm</td><td>B4 <strong>&quot;Thông tin nhu cầu + sản phẩm quan tâm&quot;</strong>; B5 <strong>&quot;Căn hộ được chọn/chốt&quot;</strong></td><td>✅ có trong sheet 04</td></tr><tr><td>Lịch sử tư vấn / giao dịch</td><td>B4 (trao đổi nhu cầu &amp; tài chính); B6 <strong>&quot;Hợp đồng + thông tin đặt cọc&quot;</strong>; B7 <strong>&quot;Lịch/tiến độ thanh toán&quot;</strong>; B8 <strong>&quot;Thông tin bàn giao&quot;</strong></td><td>✅ có trong sheet 04</td></tr><tr><td>Cơ chế đồng bộ: thời điểm tạo lead, trường dữ liệu, ai gán/phụ trách, tần suất, ID khách hàng duy nhất</td><td><strong>Sheet 04 KHÔNG nêu</strong></td><td>🟡 <strong>OQ‑NOTM‑06</strong></td></tr><tr><td>Liên kết phần mềm kế toán (trạng thái/số tiền đã thanh toán, hoá đơn điện tử)</td><td><strong>Sheet 04 KHÔNG nêu</strong>; doc <code>02</code> (Sheet 01) có nêu ở cấp hệ thống</td><td>🟡 <strong>OQ‑NOTM‑03</strong></td></tr></tbody></table><blockquote><p>Yêu cầu chi tiết phía CRM (5 chức năng trung tâm, ID khách hàng duy nhất, lịch sử trao đổi có thời gian + tài khoản thao tác, lưu bản scan theo ID) xem doc <code>02</code>. Doc này <strong>không</strong> đặc tả lại và <strong>không</strong> thêm cơ chế nào ngoài sheet.</p></blockquote><hr><h2 id="_5-thong-tin-chinh-sach-gia-đat-coc-thanh-toan-—-🟡-chua-co-du-lieu" tabindex="-1">5. Thông tin chính sách / giá / đặt cọc / thanh toán — 🟡 CHƯA có dữ liệu <a class="header-anchor" href="#_5-thong-tin-chinh-sach-gia-đat-coc-thanh-toan-—-🟡-chua-co-du-lieu" aria-label="Permalink to &quot;5. Thông tin chính sách / giá / đặt cọc / thanh toán — 🟡 CHƯA có dữ liệu&quot;">​</a></h2><p>✅ <strong>Sheet <code>04_WEB_NOTM</code> KHÔNG nêu</strong> giá bán, bảng giá, phương thức thanh toán, mức/điều kiện đặt cọc, ưu đãi hay hỗ trợ vay ở bất kỳ dòng nào (kể cả bước 6 &quot;Ký hợp đồng &amp; đặt cọc&quot; và bước 7 &quot;Thanh toán&quot; — sheet chỉ mô tả <strong>hành động</strong> thông báo/hướng dẫn/theo dõi, không kèm số liệu).</p><p>🟡 Toàn bộ nội dung này được dẫn chiếu sang <strong>doc <code>03</code> — Web Chủ đầu tư, Trang F &quot;CHÍNH SÁCH&quot;, mục F.B &quot;CHÍNH SÁCH NHÀ Ở THƯƠNG MẠI&quot;</strong> (nguồn Sheet <code>02_WEB_CHU_DAU_TU</code>), nơi ghi rõ:</p><table tabindex="0"><thead><tr><th>Điểm (nguồn doc <code>03</code>, mục F.B)</th><th>Nguyên văn / nội dung</th><th>Ảnh hưởng tới Web NOTM</th></tr></thead><tbody><tr><td>F.B.1</td><td>&quot;nội dung giá/chính sách cụ thể <strong>chỉ đưa lên sau khi CĐT ban hành</strong>&quot;</td><td>🟡 Web NOTM chưa thể hiện giá ở bước 4–6</td></tr><tr><td>F.B.2</td><td>&quot;<strong>không công bố bảng giá/ưu đãi khi chưa có chính sách chính thức</strong>&quot;</td><td>🟡</td></tr><tr><td>F.B.3</td><td>Giá bán &amp; bảng giá — &quot;<strong>Hiện chưa có bảng giá thương mại chính thức trong hồ sơ được cung cấp.</strong>&quot;</td><td>🟡 <strong>OQ‑NOTM‑11</strong></td></tr><tr><td>F.B.4</td><td>Phương thức thanh toán — chỉ điền % và mốc sau khi có chính sách chính thức</td><td>🟡 <strong>OQ‑NOTM‑03</strong></td></tr><tr><td>F.B.5</td><td>Đặt cọc &amp; ký kết giao dịch — &quot;<strong>chỉ được công bố khi sản phẩm đủ điều kiện đưa vào kinh doanh</strong>&quot;; MAYogu: &quot;cần thông tin chi tiết quy trình giao dịch&quot;</td><td>🟡 <strong>OQ‑NOTM‑01</strong></td></tr><tr><td>F.B.6</td><td>Ưu đãi &amp; chương trình bán hàng — &quot;<strong>nếu CĐT ban hành</strong>&quot;; chưa có dữ liệu ưu đãi chính thức</td><td>🟡</td></tr><tr><td>F.B.7</td><td>Hỗ trợ tài chính — cần CĐT cung cấp danh sách ngân hàng / chính sách liên kết chính thức</td><td>🟡</td></tr></tbody></table><p><strong>Kết luận mục này:</strong> ở thời điểm hiện tại <strong>CHƯA có bảng giá NOTM chính thức</strong>, do đó các FR‑NOTM‑04 → FR‑NOTM‑08 <strong>chỉ đặc tả phần nghiệp vụ/thông báo theo dõi đúng như sheet</strong>, không kèm số liệu tài chính. Khi CĐT ban hành chính sách, nội dung sẽ được bổ sung vào doc <code>03</code> (F.B) và cập nhật tương ứng ở đây.</p><hr><h2 id="_6-quy-tac-nghiep-vu-ghi-nhan-đuoc-br‐notm" tabindex="-1">6. Quy tắc nghiệp vụ ghi nhận được (BR‑NOTM) <a class="header-anchor" href="#_6-quy-tac-nghiep-vu-ghi-nhan-đuoc-br‐notm" aria-label="Permalink to &quot;6. Quy tắc nghiệp vụ ghi nhận được (BR‑NOTM)&quot;">​</a></h2><p>Sheet <code>04_WEB_NOTM</code> <strong>không có khối &quot;quy tắc nghiệp vụ&quot; riêng</strong>. Các BR dưới đây là <strong>phát biểu lại đúng câu chữ sheet</strong> (không thêm điều kiện), kèm khoảng trống để CĐT xác nhận.</p><table tabindex="0"><thead><tr><th>Mã</th><th>Quy tắc (nguyên văn / bám sheet)</th><th>Nguồn</th><th>Nhãn</th></tr></thead><tbody><tr><td>BR‑NOTM‑01</td><td>Tài khoản khách hàng được tạo sau khi <strong>xác thực số điện thoại qua OTP</strong> và <strong>nhập Họ tên, CCCD</strong>. Sheet không nêu điều kiện nào khác.</td><td>B1</td><td>✅</td></tr><tr><td>BR‑NOTM‑02</td><td>Đăng nhập bằng <strong>SĐT hoặc CCCD + mật khẩu</strong>.</td><td>B2</td><td>✅</td></tr><tr><td>BR‑NOTM‑03</td><td>Lấy lại mật khẩu qua <strong>email hoặc số điện thoại</strong>.</td><td>B3</td><td>✅ (🟡 email thu ở bước nào — OQ‑NOTM‑02)</td></tr><tr><td>BR‑NOTM‑04</td><td>Tư vấn chọn căn hộ dựa trên <strong>nhu cầu và tài chính</strong> của khách; khách <strong>trao đổi nhu cầu và tài chính với CĐT</strong>.</td><td>B4</td><td>✅</td></tr><tr><td>BR‑NOTM‑05</td><td><strong>CĐT ghi nhận/chốt căn hộ</strong>, sau đó <strong>thông báo hướng dẫn ký hợp đồng và đặt cọc</strong>.</td><td>B5</td><td>✅ (🟡 cơ chế chốt — OQ‑NOTM‑04)</td></tr><tr><td>BR‑NOTM‑06</td><td>Việc ký hợp đồng &amp; đặt cọc thực hiện <strong>theo hướng dẫn của CĐT</strong>; khách <strong>đến theo hướng dẫn</strong>.</td><td>B6</td><td>✅ (🟡 chi tiết — OQ‑NOTM‑01)</td></tr><tr><td>BR‑NOTM‑07</td><td>Khách <strong>thanh toán tiền theo tiến độ</strong>; CĐT <strong>theo dõi tiến độ thanh toán</strong>. Sheet không nêu số đợt/tỷ lệ/hình thức.</td><td>B7</td><td>✅ (🟡 OQ‑NOTM‑03)</td></tr><tr><td>BR‑NOTM‑08</td><td>Bàn giao theo <strong>thông báo lịch bàn giao</strong> của CĐT; khách <strong>đến nhận bàn giao căn hộ theo thông báo</strong>.</td><td>B8</td><td>✅ (🟡 OQ‑NOTM‑09)</td></tr></tbody></table><hr><h2 id="_7-can-xac-nhan-oq-—-sheet-bo-trong-chua-ro" tabindex="-1">7. Cần xác nhận (OQ) — sheet bỏ trống / chưa rõ <a class="header-anchor" href="#_7-can-xac-nhan-oq-—-sheet-bo-trong-chua-ro" aria-label="Permalink to &quot;7. Cần xác nhận (OQ) — sheet bỏ trống / chưa rõ&quot;">​</a></h2><p><strong>Tài liệu KHÔNG tự trả lời các câu dưới đây.</strong> Mã <code>OQ‑NOTM‑nn</code> theo quy ước <code>OQ-nn</code> của doc <code>00</code> §7, thêm scope <code>NOTM</code> để không trùng số khi gộp vào doc <code>09</code>.</p><table tabindex="0"><thead><tr><th>Mã</th><th>Bước / dòng sheet</th><th>Câu hỏi (đúng khoảng trống sheet để lại)</th><th>Ai trả lời</th></tr></thead><tbody><tr><td><strong>OQ‑NOTM‑01</strong></td><td>B5–B6</td><td><strong>Chi tiết quy trình đặt cọc &amp; ký kết giao dịch</strong>: mức/điều kiện đặt cọc, hồ sơ khách mang theo, hợp đồng mẫu, địa điểm, hình thức (sheet ghi khách &quot;Đến theo hướng dẫn của CĐT&quot; — có phương án trực tuyến không?). doc <code>03</code> F.B.5 ghi chỉ công bố &quot;khi sản phẩm đủ điều kiện đưa vào kinh doanh&quot; và MAYogu đã ghi &quot;cần thông tin chi tiết quy trình giao dịch&quot;.</td><td>CĐT (+ pháp chế)</td></tr><tr><td><strong>OQ‑NOTM‑02</strong></td><td>B1, B3</td><td><strong>Email dùng để khôi phục mật khẩu được thu thập ở bước nào?</strong> Bước 1 sheet chỉ ghi &quot;nhập Họ tên, CCCD&quot; + xác thực SĐT. Email có phải trường bắt buộc khi đăng ký không?</td><td>CĐT + MAYogu</td></tr><tr><td><strong>OQ‑NOTM‑03</strong></td><td>B7</td><td><strong>Thông tin các đợt thanh toán</strong>: số đợt, tỷ lệ, mốc thời gian, hình thức thanh toán; &quot;Lịch/tiến độ thanh toán&quot; hiển thị cho khách đến mức nào; dữ liệu do ai cập nhật — nhập tay hay đối soát tự động với <strong>phần mềm kế toán</strong> (doc <code>02</code>)?</td><td>CĐT (+ kế toán)</td></tr><tr><td><strong>OQ‑NOTM‑04</strong></td><td>B5</td><td><strong>Cơ chế &quot;chốt căn hộ&quot;</strong>: thao tác trên Web NOTM hay thực hiện ngoại tuyến rồi nhân viên cập nhật lên hệ thống? Một căn có thể được nhiều khách chốt không? Có trạng thái/khoá căn không? Có cho phép đổi hoặc huỷ căn sau khi chốt không?</td><td>CĐT + MAYogu</td></tr><tr><td><strong>OQ‑NOTM‑05</strong></td><td>B1–B2</td><td><strong>OTP &amp; bảo mật tài khoản</strong>: bước 1 có OTP khi đăng ký, bước 2 đăng nhập sheet chỉ ghi mật khẩu — có yêu cầu OTP/xác thực bổ sung khi đăng nhập hoặc khi thực hiện giao dịch (như Web NOXH) không? Số lần gửi lại OTP, thời hạn hiệu lực, quy tắc mật khẩu, xử lý khi sai nhiều lần?</td><td>CĐT + MAYogu</td></tr><tr><td><strong>OQ‑NOTM‑06</strong></td><td>Cả sheet + Sheet 01</td><td><strong>Luồng lead/dữ liệu về CRM (Nguồn 03) cụ thể</strong>: lead được tạo ở thời điểm nào (ngay khi đăng ký tài khoản hay khi phát sinh &quot;sản phẩm quan tâm&quot;)? Những trường nào đồng bộ? Lead được gán cho ai phụ trách tư vấn? Cơ chế gán/chuyển/ghi nhận lịch sử tư vấn theo <strong>ID khách hàng duy nhất</strong>?</td><td>CĐT + MAYogu (doc <code>02</code>)</td></tr><tr><td><strong>OQ‑NOTM‑07</strong></td><td>B4–B8</td><td><strong>Phân quyền phía CĐT</strong>: cột &quot;CHỦ ĐẦU TƯ&quot; ở bước 4–8 do vai trò nào thực hiện (<code>ADMIN</code> / <code>STAFF</code> / <code>ACCOUNTANT</code>)? Sheet 04 không nêu; Sheet 03 có ghi chú &quot;Làm rõ các nhóm quyền + phân quyền cho vai trò cụ thể&quot;.</td><td>CĐT</td></tr><tr><td><strong>OQ‑NOTM‑08</strong></td><td>B4</td><td><strong>Tư vấn chọn căn qua kênh nào</strong> (trực tiếp tại điểm bán / điện thoại / kênh trao đổi trên web)? Sheet chỉ ghi &quot;Tư vấn… / Trao đổi nhu cầu và tài chính với CĐT&quot;, không nêu kênh và không nêu công cụ hỗ trợ.</td><td>CĐT + MAYogu</td></tr><tr><td><strong>OQ‑NOTM‑09</strong></td><td>B8</td><td><strong>Bàn giao</strong>: kênh và nội dung &quot;Thông báo lịch bàn giao&quot;; &quot;Thông tin bàn giao&quot; gồm những trường gì; có cần lưu vết khách đã nhận bàn giao trên hệ thống không?</td><td>CĐT</td></tr><tr><td><strong>OQ‑NOTM‑10</strong></td><td>Cả sheet</td><td><strong>Cột <code>GHI CHÚ</code> trống ở cả 8 dòng</strong> — CĐT/MAYogu có ghi chú nào cần bổ sung cho từng giai đoạn không (ràng buộc, biểu mẫu, tài liệu kèm theo)?</td><td>CĐT + MAYogu</td></tr><tr><td><strong>OQ‑NOTM‑11</strong></td><td>B4–B7 (liên quan doc <code>03</code> F.B)</td><td><strong>Giá/bảng giá &amp; thời điểm công bố</strong>: hiện chưa có bảng giá NOTM chính thức (doc <code>03</code> F.B.3). Khi nào CĐT ban hành, và Web NOTM có hiển thị giá/bảng căn cho khách tự xem trước khi tư vấn không (doc <code>03</code> F.B.9 ghi MAYogu hỏi về &quot;dạng lướt list sản phẩm để lựa chọn — shopping preview&quot;)?</td><td>CĐT</td></tr><tr><td><strong>OQ‑NOTM‑12</strong></td><td>B4 (hàm ý)</td><td><strong>Danh mục sản phẩm NOTM hiển thị trên web</strong>: sheet 04 không nêu việc hiển thị danh sách căn hộ / diện tích / mặt bằng trên Web NOTM. Web NOTM có trang sản phẩm riêng hay toàn bộ việc chọn căn thực hiện qua trao đổi với CĐT?</td><td>CĐT + MAYogu</td></tr><tr><td><strong>OQ‑NOTM‑13</strong></td><td>Cả sheet</td><td><strong>Bộ trạng thái</strong>: Sheet 03 (NOXH) có bộ trạng thái hồ sơ + state machine; Sheet 04 <strong>không liệt kê trạng thái nào</strong> cho NOTM. Có cần quản lý trạng thái giao dịch NOTM (ví dụ ở mức CRM — doc <code>02</code>) không, hay chỉ ghi nhận dữ liệu?</td><td>CĐT + MAYogu</td></tr></tbody></table><hr><h2 id="_8-cross‐reference" tabindex="-1">8. Cross‑reference <a class="header-anchor" href="#_8-cross‐reference" aria-label="Permalink to &quot;8. Cross‑reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Liên quan tới doc này ở điểm nào</th></tr></thead><tbody><tr><td><code>02-phan-mem-tong-crm.md</code></td><td>Phần mềm tổng (CRM) — nơi dữ liệu <strong>Nguồn 03</strong> đổ về: ID khách hàng duy nhất, lịch sử trao đổi, tiến trình thanh toán, lưu trữ scan, kho biểu mẫu, liên kết phần mềm kế toán (§4, §6, OQ‑NOTM‑03/06)</td></tr><tr><td><code>03-web-chu-dau-tu.md</code></td><td><strong>Trang F.B — Chính sách Nhà ở thương mại</strong>: giá bán/bảng giá, phương thức thanh toán, đặt cọc &amp; ký kết giao dịch, ưu đãi, hỗ trợ tài chính — <strong>nguồn dẫn chiếu duy nhất cho phần chính sách NOTM</strong> (§5, OQ‑NOTM‑01/03/11)</td></tr><tr><td><code>04-web-noxh.md</code></td><td>Web NOXH — <strong>để so sánh</strong>: 20 bước, công cụ tự kiểm tra điều kiện, nộp/xét duyệt hồ sơ Sở Xây dựng, bốc thăm &amp; thỏa thuận chọn căn, bộ trạng thái hồ sơ, OTP (§1.4, OQ‑NOTM‑05/13)</td></tr><tr><td><code>09-open-questions.md</code></td><td>Nơi <strong>tổng hợp</strong> toàn bộ OQ‑NOTM‑01 … OQ‑NOTM‑13 (§7) kèm nguồn tab sheet + dòng, để CĐT trả lời trước khi vào đặc tả kỹ thuật</td></tr><tr><td><code>00-project-context.md</code></td><td>Nguyên tắc trung thực (§2), mô hình 5 nguồn → 1 phần mềm tổng (§4), quy ước định danh <code>FR-&lt;MOD&gt;-nn</code> / <code>BR-&lt;MOD&gt;-nn</code> / <code>OQ-nn</code> (§7), glossary NOTM/OTP/CCCD (§8)</td></tr></tbody></table><blockquote><p><strong>Ranh giới doc này:</strong> chỉ đặc tả <strong>yêu cầu</strong> cho Web NOTM bám sheet <code>04_WEB_NOTM</code>. <strong>Không</strong> gồm API contract, ERD, wireframe, test case — theo doc <code>00</code> §10, các tài liệu đó lập <strong>sau khi</strong> CĐT trả lời các OQ ở §7 / doc <code>09</code>.</p></blockquote>',78)])])}const T=n(c,[["render",g]]);export{b as __pageData,T as default};
